#include <stdio.h>
int main(void) {
    double f = 0.40, S = 10.0;   /* 可优化占比 f, 该部分加速 S */
    double total = 1.0 / ((1.0 - f) + f / S);
    printf("可优化部分占比 f = 0.40\n");
    printf("该部分加速比 S = 10.0\n");
    printf("整体加速比 = 1 / ((1-f) + f/S)\n");
    printf("           = 1 / (%g + %g) = 1 / %g = %.4f\n", (1.0 - f), f / S, (1.0 - f) + f / S, total);
    printf("并行上限(占比固定时) = 1 / (1-f) = %.4f\n", 1.0 / (1.0 - f));
    return 0;
}
